// Emulates Python's int(str) conversion used by argparse type=int and by
// NUMERIC field query parsing: surrounding whitespace allowed, optional
// sign, digits with single underscores between them (PEP 515).

const INT_RE = /^[+-]?\d(?:_?\d)*$/;

export function parsePythonInt(text) {
  const trimmed = String(text).trim();
  if (!INT_RE.test(trimmed)) return null;
  const value = Number(trimmed.replace(/_/g, ''));
  return Number.isSafeInteger(value) ? value : null;
}

