        for (let j = 0; j < terms.length; j++) {
          if (tokens[i + j] !== terms[j]) continue outer;
        }
        return true;
      }
      return false;
    },
  }),
  textRange: (field, start, end, startExcl, endExcl) => ({
    matches: (doc) =>
      doc.analyzed[field].some(
        (t) =>
          (startExcl ? t > start : t >= start) &&
          (endExcl ? t < end : t <= end),
      ),
  }),
  numRange: (field, start, end, startExcl, endExcl) => ({
    matches: (doc) => {
      const v = doc.analyzed[field];
      return (
        (startExcl ? v > start : v >= start) &&
        (endExcl ? v < end : v <= end)
      );
    },
  }),
  group: (kind, positive, negative) => ({
    matches: (doc, schema) => {
      if (positive.length === 0) return false;
      const hit =
        kind === 'and'
          ? positive.every((q) => q.matches(doc, schema))
          : positive.some((q) => q.matches(doc, schema));
      return hit && !negative.some((q) => q.matches(doc, schema));
    },
  }),
  not: (child) => ({
    matches: (doc, schema) => !child.matches(doc, schema),
  }),
  never: () => ({ matches: () => false }),
};

function levenshtein(a, b) {
  const s = [...a];
  const t = [...b];
  if (Math.abs(s.length - t.length) > 2 && s.length + t.length > 0) {
    // Quick reject only helps performance; compute fully below anyway.
  }
  let prev = Array.from({ length: t.length + 1 }, (_, j) => j);
  for (let i = 1; i <= s.length; i++) {
    const curr = [i];
    for (let j = 1; j <= t.length; j++) {
      curr[j] = Math.min(
        prev[j] + 1,
        curr[j - 1] + 1,
        prev[j - 1] + (s[i - 1] === t[j - 1] ? 0 : 1),
      );
    }
    prev = curr;
  }
  return prev[t.length];
}

// Combines parsed children into a group node; Not children become negative
// clauses. Returns null when nothing usable was parsed.
function makeGroup(kind, children) {
  const positive = [];
  const negative = [];
  for (const child of children) {
    if (child === null) continue;
    if (child._isNot) negative.push(child._isNot);
    else positive.push(child);
  }
  if (positive.length === 0 && negative.length === 0) return null;
  if (positive.length === 1 && negative.length === 0) return positive[0];
  return nodes.group(kind, positive, negative);
}

function makeNot(child) {
  if (child === null) return null;
  return { _isNot: child, matches: (doc, schema) => !child.matches(doc, schema) };
}

// --------------------------------------------------------------------- lexer

const SPECIALS = new Set(['(', ')', '"', "'", '[', ']', '{', '}']);

function lex(text) {
  const tokens = [];
  let i = 0;
  const n = text.length;
  while (i < n) {
    const c = text[i];
    if (/\s/.test(c)) {
      i++;
      continue;
    }
    if (c === '(' || c === ')') {
      tokens.push({ t: c === '(' ? 'lparen' : 'rparen', pos: i, end: i + 1 });
      i++;
      continue;
    }
    if (c === ']' || c === '}') {
      // Stray closer outside a range: ignored.
      i++;
      continue;
    }
    if (c === '"' || c === "'") {
      const start = i;
      i++;
      let buf = '';
      while (i < n && text[i] !== c) buf += text[i++];
      i++; // consume closing quote (or run off the end, tolerated)
      tokens.push({
        t: c === '"' ? 'phrase' : 'squote',
        text: buf,
        pos: start,
        end: i,
      });
      continue;
    }
    if (c === '[' || c === '{') {
      const start = i;
      const open = c;
      i++;
      let buf = '';
      while (i < n && text[i] !== ']' && text[i] !== '}') buf += text[i++];
      const close = i < n ? text[i] : open === '[' ? ']' : '}';
      i++;
      tokens.push({ t: 'range', open, close, text: buf, pos: start, end: i });
      continue;
    }
    const start = i;
    let buf = '';
    while (i < n && !/\s/.test(text[i]) && !SPECIALS.has(text[i])) {
      buf += text[i++];
    }
    tokens.push({ t: 'word', text: buf, pos: start, end: i });
  }
  // Keyword operators are recognized on whole words only.
  for (const tok of tokens) {
    if (tok.t !== 'word') continue;
    if (tok.text === 'AND' || tok.text === '&' || tok.text === '&&') tok.t = 'and';
    else if (tok.text === 'OR' || tok.text === '|' || tok.text === '||') tok.t = 'or';
    else if (tok.text === 'NOT') tok.t = 'not';
  }
  return tokens;
}

// -------------------------------------------------------------------- parser

export class QueryParser {
  constructor(fieldname, schema) {
    this.fieldname = fieldname;
    this.schema = schema;
  }

  parse(text) {
    const tokens = lex(String(text));
    this.attachFieldPrefixes(tokens);
    const parser = new Parser(tokens, this.schema, this.fieldname);
    return parser.parseQuery();
  }

  // Merges a "name:" word token directly glued to a phrase, quoted string,
  // range, or group into a field prefix, when the name is a schema field.
  attachFieldPrefixes(tokens) {
    for (let i = 0; i < tokens.length - 1; i++) {
      const tok = tokens[i];
      const next = tokens[i + 1];
      if (tok.t !== 'word' || next.pos !== tok.end) continue;
      const m = /^([\p{L}\p{N}_]+):$/u.exec(tok.text);
      if (!m || !this.schema.has(m[1])) continue;
      if (!['phrase', 'squote', 'range', 'lparen'].includes(next.t)) continue;
      next.field = m[1];
      tokens.splice(i, 1);
      i--;
    }
  }
}

class Parser {
  constructor(tokens, schema, defaultField) {
    this.toks = tokens;
    this.i = 0;
    this.schema = schema;
    this.defaultField = defaultField;
  }

  peek() {
    return this.i < this.toks.length ? this.toks[this.i] : null;
  }

  parseQuery() {
    return this.parseOr(this.defaultField);
  }

  parseOr(fieldCtx) {
    const children = [];
    for (;;) {
      const tk = this.peek();
      if (tk === null || tk.t === 'rparen') break;
      if (tk.t === 'or') {
        this.i++;
        continue;
      }
      const child = this.parseAnd(fieldCtx);
      if (child !== null) children.push(child);
    }
    return makeGroup('or', children);
  }

  parseAnd(fieldCtx) {
    const children = [];
    const first = this.parseUnary(fieldCtx);
    if (first !== null) children.push(first);
    while (this.peek() !== null && this.peek().t === 'and') {
      this.i++;
      const child = this.parseUnary(fieldCtx);
      if (child !== null) children.push(child);
    }
    return makeGroup('and', children);
  }

  parseUnary(fieldCtx) {
    const tk = this.peek();
    if (tk === null) return null;
    if (tk.t === 'not') {
      this.i++;
      return makeNot(this.parseUnary(fieldCtx));
    }
    if (tk.t === 'and' || tk.t === 'or') {
      // Stray leading operator (e.g. "AND ab"): ignored, like whoosh.
      this.i++;
      return this.parseUnary(fieldCtx);
    }
    return this.parseAtom(fieldCtx);
  }

  parseAtom(fieldCtx) {
    const tk = this.peek();
    if (tk === null) return null;
    if (['rparen', 'and', 'or', 'not'].includes(tk.t)) return null;
    this.i++;
    const field = tk.field || fieldCtx;
    switch (tk.t) {
      case 'lparen': {
        const inner = this.parseOr(field);
        if (this.peek() !== null && this.peek().t === 'rparen') this.i++;
        return inner;
      }
      case 'phrase':
        return this.buildPhrase(tk.text, field);
      case 'squote':
        return this.buildAnalyzed(tk.text, field);
      case 'range':
        return this.buildRange(tk, field);
      default:
        return this.buildWord(tk.text, field);
    }
  }

  // A phrase: analyzed tokens must appear consecutively.
  buildPhrase(text, field) {
    if (this.schema.isNumeric(field)) return nodes.never();
    const terms = standardTokens(text);
    if (terms.length === 0) return null;
    if (terms.length === 1) return nodes.term(field, terms[0]);
    return nodes.phrase(field, terms);
  }

  // Single-quoted text: analyzed as a plain word (no wildcard/fuzzy).
  buildAnalyzed(text, field) {
    if (this.schema.isNumeric(field)) {
      const value = parsePythonInt(text);
      return value === null ? nodes.never() : nodes.numTerm(field, value);
    }
    const terms = standardTokens(text);
    if (terms.length === 0) return null;
    if (terms.length === 1) return nodes.term(field, terms[0]);
    return makeGroup(
      'or',
      terms.map((t) => nodes.term(field, t)),
    );
  }

  buildWord(raw, fieldCtx) {
    let text = raw;
    let fuzzyDist = null;
    // Boost suffix is parsed but has no effect on matching.
    const boost = /\^[\d.]+$/.exec(text);
    if (boost) text = text.slice(0, boost.index);
    const fuzzy = /~(\d*(?:\.\d+)?)$/.exec(text);
    if (fuzzy) {
      fuzzyDist = fuzzy[1] === '' ? 1 : Number(fuzzy[1]);
      text = text.slice(0, fuzzy.index);
    }

    let field = fieldCtx;
    let rest = text;
    const fm = /^([\p{L}\p{N}_]+):([\s\S]+)$/u.exec(text);
    if (fm && this.schema.has(fm[1])) {
      field = fm[1];
      rest = fm[2];
    }

    if (this.schema.isNumeric(field)) {
      if (/[*?]/.test(rest)) {
        return rest === '*' ? nodes.numAny(field) : nodes.never();
      }
      if (fuzzyDist !== null) return nodes.never();
      const value = parsePythonInt(rest);
      return value === null ? nodes.never() : nodes.numTerm(field, value);
    }

    if (fuzzyDist !== null) {
      return nodes.fuzzy(field, rest.toLowerCase(), fuzzyDist);
    }
    if (/[*?]/.test(rest)) {
      return nodes.wildcard(field, rest.toLowerCase());
    }
    return this.buildAnalyzed(rest, field);
  }

  buildRange(tk, field) {
    const parts = tk.text.split(/\s+TO\s+/);
    if (parts.length !== 2 || parts[0].trim() === '' || parts[1].trim() === '') {
      // Not a range after all (e.g. "[ab to cd]"): treat as plain text.
      return this.buildAnalyzed(tk.text, field);
    }
    const startExcl = tk.open === '{';
    const endExcl = tk.close === '}';
    if (this.schema.isNumeric(field)) {
      const start = parsePythonInt(parts[0].trim());
      const end = parsePythonInt(parts[1].trim());
      if (start === null || end === null) return nodes.never();
      return nodes.numRange(field, start, end, startExcl, endExcl);
    }
    return nodes.textRange(
      field,
      parts[0].trim().toLowerCase(),
      parts[1].trim().toLowerCase(),
      startExcl,
      endExcl,
    );
  }
}

